package io.nebulaflow.rag;
import com.fasterxml.jackson.core.*; import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.transaction.Transactional; import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class RagService { private static final TypeReference<Map<String,Object>> MAP=new TypeReference<>(){}; private final RagChunkRepository repo; private final ObjectMapper mapper; private final EmbeddingModel model; private final RagChunker chunker=new RagChunker(); private final int size,overlap,maxTopK;
 public RagService(RagChunkRepository repo,ObjectMapper mapper,EmbeddingModel model,@Value("${nebulaflow.rag.chunk-size:1200}")int size,@Value("${nebulaflow.rag.chunk-overlap:150}")int overlap,@Value("${nebulaflow.rag.max-top-k:20}")int maxTopK){this.repo=repo;this.mapper=mapper;this.model=model;this.size=size;this.overlap=overlap;this.maxTopK=maxTopK;}
 @Transactional public RagModels.IngestResult ingest(String tenant,String collection,RagModels.Document doc,Integer requestedSize,Integer requestedOverlap){scope(tenant,collection);int cs=requestedSize==null?size:requestedSize,ov=requestedOverlap==null?overlap:requestedOverlap;List<String> chunks=chunker.split(doc.text(),cs,ov);repo.deleteByTenantIdAndCollectionNameAndDocumentId(tenant,collection,doc.id());String meta=json(doc.metadata());Instant now=Instant.now();List<RagChunkEntity> rows=new ArrayList<>();for(int i=0;i<chunks.size();i++)rows.add(new RagChunkEntity(UUID.randomUUID(),tenant,collection,doc.id(),i,chunks.get(i),meta,json(model.embed(chunks.get(i))),now));repo.saveAll(rows);return new RagModels.IngestResult(collection,doc.id(),rows.size());}
 @Transactional public RagModels.QueryResult query(String tenant,String collection,String query,int topK,double minScore){scope(tenant,collection);if(query==null||query.isBlank())throw new IllegalArgumentException("query is required");if(topK<1||topK>maxTopK)throw new IllegalArgumentException("topK must be between 1 and "+maxTopK);if(minScore<-1||minScore>1)throw new IllegalArgumentException("minScore must be between -1 and 1");List<Double> q=model.embed(query);List<RagModels.Match> matches=repo.findByTenantIdAndCollectionName(tenant,collection).stream().map(row->match(row,q)).filter(x->x.score()>=minScore).sorted(Comparator.comparingDouble(RagModels.Match::score).reversed()).limit(topK).toList();String context=matches.stream().map(x->"[source="+x.documentId()+", chunk="+x.chunkIndex()+"]\n"+x.content()).reduce((a,b)->a+"\n\n"+b).orElse("");return new RagModels.QueryResult(collection,query,matches,context);}
 private RagModels.Match match(RagChunkEntity row,List<Double> q){List<Double> v=read(row.getEmbeddingJson());if(v.size()!=q.size())throw new IllegalStateException("stored embedding dimensions do not match configured model");double score=0;for(int i=0;i<v.size();i++)score+=v.get(i)*q.get(i);return new RagModels.Match(row.getDocumentId(),row.getChunkIndex(),row.getContent(),score,readMap(row.getMetadataJson()));}
 private List<Double> read(String s){try{return mapper.readValue(s,new TypeReference<List<Double>>(){});}catch(JsonProcessingException e){throw new IllegalStateException("invalid stored embedding",e);}} private Map<String,Object> readMap(String s){try{return mapper.readValue(s,MAP);}catch(JsonProcessingException e){throw new IllegalStateException("invalid stored metadata",e);}} private String json(Object x){try{return mapper.writeValueAsString(x);}catch(JsonProcessingException e){throw new IllegalStateException("could not serialize RAG payload",e);}} private static void scope(String tenant,String collection){if(tenant==null||tenant.isBlank())throw new IllegalArgumentException("tenantId is required");if(collection==null||collection.isBlank()||collection.length()>160)throw new IllegalArgumentException("invalid collection");} }